    completed_check:
      type: all
      checks:
        - type: file_exists
          path: "required.txt"
        - type: any
          checks:
            - type: file_exists
              path: "option_a.txt"
            - type: file_exists
              path: "option_b.txt"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let check = config.steps["complex"].completed_check.as_ref().unwrap();
